from abc import ABCMeta, abstractmethod
import six
from taf.internal.managedobject import ManagedObject


@six.add_metaclass(ABCMeta)
class FileGetter(ManagedObject):
    """
    Object, which allows to get files from a remote host to the local host.
    """

    @abstractmethod
    def get_file(self, source_path, target_path):
        """
        Get a file at a source path on the remote host to a target path on the local host.

        :param str source_path: source path on remote host
        :param str target_path: target path on local host
        """
